// Brand packs: everything one brand's demo needs (seed, facts, brief, moves, card pages, pools, config).
// The default brand context is Brew itself (public/data/brew.js, the landing's seed): no brand data, never listed, routed or
// watched. Every brand is generated by the build
// (build.js) into .brands/<slug>/ and mirrored to gs://<bucket>/brands/<slug>/.
import { nextFestival } from './calendar.js';
import { healthFrom, HEALTH_V, healthKey, geoOf } from './health.js';
import { numbersFor, healSeedNumbers, numberRows, dayOf } from './pack-numbers.js'; // one number, one source, for every screen
import { catalogOf, matchProduct, junkPhoto, cardProduct, cardAssetText } from './product-match.js';
import fs from 'node:fs';
import vm from 'node:vm';
import path from 'node:path';
import { allowedFrom } from './fact-gate.js';
import { demoFor, withDemo, DEMO_V } from './demo-data.js';
import { dejargon } from './plain.js'; // plain words on saved source names
import { brewFile } from './brew-name.js'; // packs written before the rename say ShopOS
import { socialize, readSocial } from './social-feed.js'; // what listening heard and the ideas stream, as cards
import { fitCta, fillMake, readSrc } from './cards-gen.js';
import { cleanBrief, renderBrief } from './brief.js'; // a saved brief's "null" cells heal at load
import { aboutOf, OLD_ABOUT } from './derive.js'; // a saved config.about written by the old rule heals at load
import { prototypeConnectors } from './seed-template.js'; // DUMMY: connector copy that promises no action
